export function escHTML(value) {
    const entityMap = {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#039;",
    };
    return String(value ?? "").replace(/[&<>"']/g, (c) => entityMap[c]);
}
export function escJS(value) {
    const s = String(value ?? "");
    return s.replace(/['"\\\/\x00-\x1F\x80-\uFFFF]/g, (c) => c === "\\"
        ? "\\\\"
        : c === "\n"
            ? "\\n"
            : c === "\r"
                ? "\\r"
                : c === "\t"
                    ? "\\t"
                    : c.charCodeAt(0) < 32
                        ? `\\x${c.charCodeAt(0).toString(16).padStart(2, "0")}`
                        : `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`);
}
export function escURL(value) {
    const s = String(value ?? "");
    // Block dangerous protocols for href/src attributes
    if (/^(javascript|data|vbscript):/i.test(s.trim())) {
        return "#invalid-protocol";
    }
    return encodeURI(s);
}
